contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint minSum, uint depositAmount, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance");

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint recordedBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalanceBefore = address(c).balance;

        require(recordedBefore < minSum, "precondition: balance below MinSum");

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = true; // this branch should not be reached
        }

        assert(reverted && c.balances(address(this)) == recordedBefore && address(c).balance == cBalanceBefore);
    }

    receive() external payable {}
}

