pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 minSum, uint256 depositAmount, uint256 am) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 recordedBefore;
        try c.balances(address(this)) returns (uint256 __r) { recordedBefore = __r; } catch { return; }
        uint cBalanceBefore = address(c).balance;
        vm.assume(recordedBefore < minSum);
        bool reverted;
        try c.Collect(am) {
            reverted = true; // this branch should not be reached
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.balances(address(this)) == recordedBefore && address(c).balance == cBalanceBefore);
    }

    function testFuzz_run(uint256 minSum, uint256 depositAmount, uint256 am) public {
        _run(minSum, depositAmount, am);
    }

    receive() external payable {}
}
